A **Constructor** is a special member function invoked automatically when an object is created. It has the same name as the class and initializes the object. A **Destructor** is invoked automatically when an object is destroyed. It has the same name as the class preceded by a tilde (~) and deallocates resources.

**Example:**
```cpp
#include <iostream>
using namespace std;

class Demo {
public:
    // Constructor
    Demo() {
        cout << "Constructor called! Object created." << endl;
    }

    // Destructor
    ~Demo() {
        cout << "Destructor called! Object destroyed." << endl;
    }
};

int main() {
    cout << "Inside main function." << endl;
    {
        Demo obj; // Constructor is called here
    } // Destructor is called here as obj goes out of scope
    cout << "Exiting main function." << endl;
    return 0;
}
```
**Output:**
Inside main function.
Constructor called! Object created.
Destructor called! Object destroyed.
Exiting main function.

Function Overloading is a feature in C++ where two or more functions can have the same name but different parameters (different type, number, or sequence of parameters). It is a form of compile-time polymorphism.

**Example:**
```cpp
#include <iostream>
using namespace std;

class MathOperations {
public:
    // Function with two int parameters
    int add(int a, int b) {
        return a + b;
    }

    // Function with three int parameters
    int add(int a, int b, int c) {
        return a + b + c;
    }

    // Function with double parameters
    double add(double a, double b) {
        return a + b;
    }
};

int main() {
    MathOperations math;
    cout << "Add 2 ints: " << math.add(10, 20) << endl;
    cout << "Add 3 ints: " << math.add(10, 20, 30) << endl;
    cout << "Add 2 doubles: " << math.add(5.5, 2.5) << endl;
    return 0;
}
```

A **friend function** in C++ is a function that is not a member of a class but has access to its private and protected members. It is declared inside the class using the `friend` keyword.

**Example:**
```cpp
#include <iostream>
using namespace std;

class Box {
private:
    int width;
public:
    Box(int w) : width(w) {}

    // Declare friend function
    friend void printWidth(Box b);
};

// Definition of friend function (not a member function)
void printWidth(Box b) {
    // Can directly access private member 'width'
    cout << "Width of box is: " << b.width << endl;
}

int main() {
    Box myBox(15);
    printWidth(myBox); // Calling friend function
    return 0;
}
```

To read from a file in C++, we use the `ifstream` class available in the `<fstream>` header.

**Example Program:**
```cpp
#include <iostream>
#include <fstream>
#include <string>
using namespace std;

int main() {
    // Create an input file stream object and open file
    ifstream inputFile("data.txt");
    string line;

    // Check if the file opened successfully
    if (inputFile.is_open()) {
        cout << "File opened successfully. Reading contents:\n";
        // Read the file line by line
        while (getline(inputFile, line)) {
            cout << line << endl;
        }
        // Close the file after reading
        inputFile.close();
    } else {
        cout << "Error: Unable to open the file." << endl;
    }
    return 0;
}
```

