}
```

Access specifiers define the scope and visibility of class members (data and functions).

1. **Public (`public`)**: Members declared public are accessible from anywhere outside the class, within the entire program.
2. **Private (`private`)**: Members declared private are accessible only from within the class itself. They cannot be accessed by derived classes or outside functions (unless they are friends).
3. **Protected (`protected`)**: Members act similar to private members but with one key difference: they CAN be accessed by child/derived classes.

**Example:**
```cpp
class Base {
private:
    int priv_data;    // Only accessible inside Base
protected:
    int prot_data;    // Accessible in Base and Derived classes
public:
    int pub_data;     // Accessible anywhere
};

class Derived : public Base {
public:
    void display() {
        // priv_data = 10; // ERROR: Not accessible
        prot_data = 20; // VALID
        pub_data = 30;  // VALID
    }
};

int main() {
    Base b;
    // b.priv_data = 1; // ERROR
    // b.prot_data = 2; // ERROR
    b.pub_data = 3;     // VALID
    return 0;
}
```

```cpp
#include <iostream>
using namespace std;

class Counter {
private:
    int value;
public:
    // Constructor
    Counter(int v = 0) : value(v) {}

    // Overloading prefix increment operator (++)
    void operator++() {
        ++value;
    }

    // Overloading prefix decrement operator (--)
    void operator--() {
        --value;
    }

    // Function to display the value
    void display() const {
        cout << "Current Value: " << value << endl;
    }
};

int main() {
    Counter c(10);

    cout << "Initial state:\n";
    c.display();

    cout << "\nApplying Prefix Increment (++):\n";
    ++c; // Calls operator++()
    c.display();

    cout << "\nApplying Prefix Decrement (--):\n";
    --c; // Calls operator--()
    c.display();

    return 0;
}
```

```cpp
#include <iostream>
using namespace std;

class Number {
private:
    int x, y;
public:
    // Constructor
    Number(int a = 0, int b = 0) : x(a), y(b) {}

    // Overloading unary minus (-) operator
    void operator-() {
        x = -x;
        y = -y;
    }

    // Function to display values
    void display() const {
        cout << "x = " << x << ", y = " << y << endl;
    }
};

int main() {
    Number num(15, -20);

    cout << "Original values:\n";
    num.display();

    // Applying unary minus
    -num; 

    cout << "Values after applying unary minus (-):\n";
    num.display();

    return 0;
}
```

Hierarchical inheritance is a type of inheritance where multiple derived classes inherit from a single base class.

```cpp
#include <iostream>
using namespace std;

// Base Class
class Number {
protected:
    int num;
public:
    void setNumber(int n) {
        num = n;
    }
};

// Derived Class 1
class Square : public Number {
public:
    int getSquare() {
        return num * num;
    }
};

// Derived Class 2
class Cube : public Number {
public:
    int getCube() {
        return num * num * num;
    }
};

int main() {
    Square sqObj;
    Cube cbObj;
    int val;

    cout << "Enter a number: ";
    cin >> val;

    // Using Square object
    sqObj.setNumber(val); // Inherited from Base
    cout << "Square of " << val << " is: " << sqObj.getSquare() << endl;

    // Using Cube object
    cbObj.setNumber(val); // Inherited from Base
    cout << "Cube of " << val << " is: " << cbObj.getCube() << endl;

    return 0;
}
```
**Explanation:**
The `Number` class acts as the base class containing the data member `num` and a setter method. Both `Square` and `Cube` classes inherit from `Number` independently (hierarchical setup). One computes the square, and the other computes the cube using the inherited `num`.

