In C++, we can define our own custom exceptions by creating classes that inherit from `std::exception` and overriding the `what()` method.

**Example:**
```cpp
#include <iostream>
#include <exception>
using namespace std;

// User-defined exception class
class AgeException : public exception {
public:
    // Override what() method
    const char* what() const throw() {
        return "Age must be 18 or older to vote!";
    }
};

int main() {
    int age;
    cout << "Enter your age: ";
    cin >> age;

    try {
        if (age < 18) {
            throw AgeException(); // Throwing custom exception
        }
        cout << "You are eligible to vote." << endl;
    }
    catch (AgeException& e) {
        // Catching custom exception
        cout << "Caught Custom Exception: " << e.what() << endl;
    }
    return 0;
}
```

```cpp
#include <iostream>
using namespace std;

// Template function for Bubble Sort
template <typename T>
void bubbleSort(T arr[], int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                // Swap elements
                T temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }
}

// Utility function to print array
template <typename T>
void printArray(T arr[], int n) {
    for (int i = 0; i < n; i++) {
        cout << arr[i] << " ";
    }
    cout << endl;
}

int main() {
    // Testing with integer array
    int intArr[] = {64, 34, 25, 12, 22, 11, 90};
    int n1 = sizeof(intArr)/sizeof(intArr[0]);
    cout << "Unsorted Integer Array: ";
    printArray(intArr, n1);
    bubbleSort(intArr, n1);
    cout << "Sorted Integer Array: ";
    printArray(intArr, n1);

    // Testing with float array
    float floatArr[] = {4.2, 1.5, 9.8, 3.3};
    int n2 = sizeof(floatArr)/sizeof(floatArr[0]);
    cout << "\nUnsorted Float Array: ";
    printArray(floatArr, n2);
    bubbleSort(floatArr, n2);
    cout << "Sorted Float Array: ";
    printArray(floatArr, n2);

    return 0;
}
```

Associative containers in the C++ STL implement sorted data structures that can be quickly searched (typically using Red-Black trees). Keys are unique (in `set` and `map`) or repeatable (in `multiset` and `multimap`). 

**Demonstration using `std::map`:**
A `map` stores data in Key-Value pairs where keys are unique.

```cpp
#include <iostream>
#include <map>
#include <string>
using namespace std;

int main() {
    // Create a map (associative container) with string keys and int values
    map<string, int> studentMarks;

    // Inserting elements
    studentMarks["Alice"] = 85;
    studentMarks["Bob"] = 92;
    studentMarks["Charlie"] = 78;

    // Alternately using insert()
    studentMarks.insert(make_pair("Diana", 88));

    cout << "--- Student Marks (Auto-sorted by Key) ---\n";
    // Traversing the map using an iterator
    for (map<string, int>::iterator it = studentMarks.begin(); it != studentMarks.end(); ++it) {
        cout << "Name: " << it->first << ", Marks: " << it->second << endl;
    }

    // Finding an element
    string searchName = "Bob";
    if (studentMarks.find(searchName) != studentMarks.end()) {
        cout << "\nFound " << searchName << "'s marks: " << studentMarks[searchName] << endl;
    } else {
        cout << searchName << " not found." << endl;
    }

    return 0;
}
```

A stack is a container adapter in C++ STL that operates on the LIFO (Last In First Out) principle. Elements are pushed to the top and popped from the top.

```cpp
#include <iostream>
#include <stack>
using namespace std;

void displayStackStatus(stack<int> s) {
    cout << "Current stack size: " << s.size() << endl;
    if (s.empty()) {
        cout << "Stack is empty.\n";
    } else {
        cout << "Top element: " << s.top() << "\n";
    }
}

int main() {
    stack<int> myStack;

    cout << "--- Pushing elements into stack ---\n";
    myStack.push(10);
    myStack.push(20);
    myStack.push(30);

    displayStackStatus(myStack);

    cout << "\n--- Popping elements from stack ---\n";
    while (!myStack.empty()) {
        cout << "Popping: " << myStack.top() << endl;
        myStack.pop(); // Removes the top element
    }

    cout << "\n--- Stack Status after popping ---\n";
    displayStackStatus(myStack);

    return 0;
}
```
